from pathlib import Path
import json,hashlib,subprocess
w=Path(__file__).resolve().parent;r=w.parents[2];tool=r/'releases/3.1.0-rc.3/tools'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def run(name,args):
 p=subprocess.run(list(map(str,args)),cwd=r,capture_output=True);(w/(name+'.stdout')).write_bytes(p.stdout);(w/(name+'.stderr')).write_bytes(p.stderr);print(name,p.returncode,flush=True);p.check_returncode()
