s=read(w/'SOURCE_CARRIER.json');b=read(w/'NATIVE_BINDING.json');files=[w/n for n in ['ACTIVATION.md','PREPUBLICATION.md','PREDECESSOR_DISPOSITIONS.json','COMPANION_DISPOSITIONS.json','NATIVE_BINDING.json','NATIVE_ASSESSMENT_BINDING.json','FINAL_NATIVE_IDENTITY.json','SOURCE_CARRIER.json','context/FINAL_FREEZE.json','context/FINAL_RESULT.json','context/SOURCE_AMENDMENT_CONTROLS.json','context/regeneration-check-03.stdout','assessed-packaged/RESULT.json','PRODUCT_EXTRACTION_03.json','visual/PACKAGE_SELECTION.json','visual/RESULT.json','visual/PREDECESSOR_COMPARISON.json','visual/browser-rc3-01/RESULT.json','manager-checks/RESULT.json','method-02/PACKAGE_CHECK.json','ref-tests-02/RESULT.json','assessment/native-02/ASSESSMENT.md','assessment/native-02/EXECUTION.json','assessment/semantic-01/ASSESSMENT.md','assessment/semantic-03/ASSESSMENT.md','assessment/semantic-03/EXECUTION.json','assessment/semantic-03/TRANSCRIPTION.json','run_public_install.py','context/run_distribution_checks.py','GITHUB_RELEASE_NOTES.md']]
