files += [p for p in tool.iterdir() if p.is_file()]
selection=read(r/'releases/3.1.0-rc.3/COHORT_INPUTS.json');files += [w/'assets'/n for n in selection['assets'] if not n.startswith('cohort-release-')]
q={'kind':'stdo.prepublication-qualified-subjects/1','status':'qualified-for-declared-prepublication-claims','carrier':s['carrier'],'native':s['native'],'expected_remote_main':s['base'],'scope_record':str(w/'PREPUBLICATION.md'),'qualified_files':[{'path':str(p),'sha256':sha(p)} for p in files],'limits':['Finite declared subjects only; identity gate and public installation remain separate.','No human exact-cut acceptance, whole-method qualification or consumer adoption.','Actual external Claude-family review independent of Codex construction; earlier Claude-family architectural influence disclosed.']};save(w/'PREPUBLICATION_QUALIFICATION.json',q)
