plan=read(w/'REF_PLAN.json');rows=[]
for row in plan['refs']:
 obj=git('rev-parse',row['source']);assert obj==row['object'];typ=git('cat-file','-t',obj);record={**row,'object_type':typ,'peel':git('rev-parse',obj+'^{commit}')}
 if typ=='tag':record['tag_body']=git('cat-file','tag',obj)
 assert record['peel']==row['commit'];rows.append(record)
products=[]
