a=w/'assessment/identity-01';a.mkdir();f=[w/'REF_PLAN.json',w/'TAG_INTERNAL_READBACK.json',w/'COHORT_DRAFT.json',w/'PREPUBLICATION_QUALIFICATION.json',w/'SOURCE_CARRIER.json'];save(a/'FREEZE.json',{'carrier':s['carrier'],'native':s['native'],'files':[{'path':str(p),'sha256':sha(p)} for p in f]})
